#!/bin/sh
# -*- coding: utf-8 -*-
"exec" "env" "TANIUM_SENSOR=1" "`pwd`/python27/python" "$0" "$@"

import traceback
import sys
import re
import hashlib
import os
import imp

try:
    import tanium
    from tanium import util
    from tanium import six
    from tanium import subproc
    from tanium import os_help
    from tanium.sensor_io import sensor_input
    from incident_response import tanium_process
    from tanium_process import exceptions as tproc_exceptions
    from incident_response.taniumlib import hash as thash
except (OSError, RuntimeError, ImportError, AttributeError) as e:
    em = 'Error locating necessary files. Ensure Incident Response Tools are deployed. Error was: {}'.format
    sys.exit(em(e))

PASSABLE_EXCEPTIONS = (tproc_exceptions.ZombieProcess, tproc_exceptions.AccessDenied, tproc_exceptions.NoSuchProcess)

sep = '|'

mac_blacklist = [
    'epagd',
    'BDUpdDaemon',
    'BDLDaemon',
    'BDCoreIssues',
    'EndpointSecurityforMac',
    'kill',
]

other_blacklist = [
    '[vvar]',
    '[vdso]',
    '[anon]',
    '[stack]',
    '[vsyscall]',
    '[heap]',
]


def is_exe(path):
    magics = [
        # ELF
        '\x7f\x45\x4c\x46',
        # MZ
        '\x4d\x5a\x90\x00',
        # Mach-O
        '\xcf\xfa\xed\xfe',
        '\xce\xfa\xed\xfe',
    ]
    try:
        with open(path, 'rb') as tfile:
            return tfile.read(4) in magics
    except IOError:
        return False


def get_path(line):
    '''
    Expects an input line where the last part of the line
    is a path to a dylib file.  For example:
    __TEXT  00007fff594cd000-00007fff594d1000 [ 16K 16K 0K 0K] r-x/r-x SM=COW  /some/path to/libsystem_sandbox.dylib

    also we could have a path without '/':
    __TEXT  00007fff594cd000-00007fff594d1000 [ 16K 16K 0K 0K] r-x/r-x SM=COW  libsystem_sandbox.dylib
    '''
    loc = line.find(' /')
    if loc == -1:
        return line.split()[-1]
    return line[loc + 1:]


def get_wl_modules(answers, proc, alg, seen_paths):
    # This function handles both Windows and Linux
    stack = re.compile(r'\[stack:\d+\]')
    for mod in proc.memory_maps():
        if mod.path in other_blacklist:
            continue
        elif re.search(stack, mod.path.lower()):
            continue
        elif not os.path.exists(mod.path):
            answers.add('{path}{sep}{fhash}'.format(path=mod.path, sep=sep, fhash='Unable to hash file (file not found)'))
            seen_paths.add(mod.path.lower())
            continue
        elif not is_exe(mod.path):
            continue
        elif mod.path.lower() in seen_paths:
            continue
        answers.add('{path}{sep}{fhash}'.format(path=mod.path, sep=sep, fhash=alg.hash_file(mod.path)))
        seen_paths.add(mod.path.lower())


def get_mac_modules(answers, proc, alg, seen_paths):
    # This function uses the lsof utility instead of vmmap
    # The downside is that we get less information, but it is quicker.
    so = re.compile(r'.*\.so$')
    dylib = re.compile(r'.*\.dylib$')
    if proc.pid == 0:
        answers.add('Unable to enumerate modules for process {}'.format(proc.name()))
        return
    try:
        with open(os.devnull, 'w') as FNULL:
            lsof_out = six.ensure_str(subproc.subprocess.check_output(['lsof', '-w', '-p', str(proc.pid)], stderr=FNULL))
    except subproc.subprocess.CalledProcessError as e:
        answers.add('TSE-Error: {}'.format(e))
        return
    for line in lsof_out.split("\n"):
        try:
            if re.search(dylib, line) or re.search(so, line):
                tpath = get_path(line)
                if tpath.lower() in seen_paths:
                    continue
                elif not os.path.exists(tpath):
                    answers.add('{path}{sep}{fhash}'.format(path=tpath, sep=sep, fhash='Unable to hash file (file not found)'))
                    seen_paths.add(tpath.lower())
                    continue
                elif is_exe(tpath):
                    answers.add('{path}{sep}{fhash}'.format(path=tpath, sep=sep, fhash=alg.hash_file(tpath)))
                    seen_paths.add(tpath.lower())
        except IndexError:
            pass
        except Exception as e:
            answers.add('TSE-Error: {}'.format(e))


def get_modules(alg):
    answers = set()
    seen_paths = set()
    for proc in tanium_process.process_iter():
        try:
            if proc.name() not in mac_blacklist and proc.name() not in other_blacklist:
                if os_help.is_mac():
                    # Mac only
                    get_mac_modules(answers, proc, alg, seen_paths)
                else:
                    # Windows and Linux
                    get_wl_modules(answers, proc, alg, seen_paths)
        except Exception as e:
            if e in PASSABLE_EXCEPTIONS:
                if e is tproc_exceptions.AccessDenied:
                    answers.add('TSE-Error: AccessDenied: Process PID={}, name={}'.format(proc.pid, proc.name()))
                else:
                    pass
            else:
                answers.add('TSE-Error: {}'.format(e))
    if not answers:
        answers.add('No matches')
    return list(sorted(answers))


def sensor_main():
    inputs = sensor_input.SensorInputs()
    inputs.add_param('hash_alg', 'SHA256', 'md5')
    hash_alg = inputs.get_param('hash_alg')

    hash_alg = getattr(hashlib, hash_alg.lower(), hashlib.md5)
    return get_modules(thash.Hasher(hash_alg))

if __name__ == '__main__':
    try:
        results = sensor_main()
    except Exception:
        results = traceback.format_exc().replace('\n', '->')
    tanium.results.add(results)

