# -*- coding: utf-8 -*-
import re import sys import traceback
try: import tanium from tanium.sensor_io import sensor_input try: from incident_response.taniumlib import hash as thash except ImportError: from taniumlib import hash as thash from incident_response import exceptions as tir_exceptions from incident_response.persistence import autoruns as ar from incident_response.persistence import sign_cache
except (OSError, RuntimeError, ImportError, AttributeError) as e: em = 'Error locating necessary files. Ensure Incident Response Tools are deployed. Error was: {}'.format sys.exit(em(e))
def _get_single_line_traceback(): trace_lines = traceback.format_exc().strip() return re.sub(r'(\r?\n)+ *', '->', trace_lines)
def stringify_result(result): """Applies a formatting string to result object.
This produces output from results which are appropriate as sensor answer lines.
Args: result (incident_response.persistence.mac._common.AutoRunResult): An AutoRunResult object to apply this format to.
Returns: str: A formatted string representation of the AutoRunResult. """ sep = '|#' a_fmt = '{0.autorun_source_path}{s}{0.autorun_name}{s}{0.autorun_executable}{s}{cat}{s}' \ '{0.autorun_command_line}{s}{0.autorun_hash}'
# Sometimes the 'result' is just an error string, like: # Error: Could not parse plist file /path/to/file.plist ... if hasattr(result, 'autorun_category'): return a_fmt.format(result, cat=result.autorun_category, s=sep) else: return result
def sensor_main(): inputs = sensor_input.SensorInputs() inputs.add_param('alg', 'MD5', 'MD5') inputs.add_param('include_apple', '1', '1')
autoruns_answers = list() alg = inputs.get_param('alg') or 'md5' incl_str = inputs.get_param('include_apple') or '0' include_apple = bool(int(incl_str)) hide_apple = not include_apple
# pass class that can be instantiated, not the object. hc = getattr(thash.Hasher, alg.lower()) hash_signed_cache = sign_cache.HashesSignedByTrustedOrgCache.from_disk(continue_if_missing=True)
try: result_bundle = ar.get_autoruns(hasher_class=hc, hide_signed=hide_apple, hash_to_signed_cache=hash_signed_cache) autoruns_answers.extend([stringify_result(res) for res in result_bundle.all_results + result_bundle.error_strings])
except tir_exceptions.AutoRunError as e: autoruns_answers.append(e)
return autoruns_answers
if __name__ == '__main__': try: r = sensor_main() except Exception: r = _get_single_line_traceback()
try: tanium.results.add(r) except (AttributeError, NameError): print('\n'.join(r))

