#!/bin/sh
#INCLUDE=index/safe_launch.sh #INCLUDE=index/FileQueryViewName.sh #INCLUDE=index/AppendWhereGlob.sh #INCLUDE=index/CheckEPIArgSupport.sh #INCLUDE=index/GenerateValidQueryInput.sh #@START_INCLUDES_HERE #------------ INCLUDES START - Do not edit between this line and INCLUDE ENDS ----- #- Begin file: index/GenerateValidQueryInput.sh
percent_decode() { local data=$(echo "$1" | sed 's/%/\\\x/g') command printf '%b' "$data" }
GenerateValidQueryInput() { local strIn="$1" local strDefaultValue="$2" if [ "$strIn" = "" ] || [ "`echo "$strIn" | egrep -v '^\|\|'`" = "" ]; then if [ "$strDefaultValue" = "" ]; then echo \* else echo "$strDefaultValue" fi else # remove any trailing backslash echo "$strIn" | sed -e 's/\\$//' fi }
GenerateValidRegexInput() { local strIn="$1" local strDefaultValue="$2" if [ "$strIn" = "" ] || [ "$strIn" = "*" ] || [ "`echo "$strIn" | egrep -v '^\|\|'`" = "" ]; then if [ "$strDefaultValue" = "" ]; then echo \.\+ else echo "$strDefaultValue" fi else echo "$strIn" fi } #- End file: index/GenerateValidQueryInput.sh #- Begin file: index/CheckEPIArgSupport.sh CheckEPIArgSupport() { local EPI="$1" local strOptionalArg="$2"
if [ -x "$EPI" ]; then ${EPI} ${strOptionalArg} -v 1>/dev/null 2>&1 if [ $? = 0 ]; then echo "True" else echo "False" fi fi }
CheckEPIRegexSupport() { local EPI="$1" regexFlagSupported=$( CheckEPIArgSupport "${EPI}" "--regex-search" ) echo $regexFlagSupported } #- End file: index/CheckEPIArgSupport.sh #- Begin file: index/AppendWhereGlob.sh
# Replace glob wildcards '?'' and '*' to SQLite LIKE '_' and '%' GlobToLike() { local strGlob="$1" strGlob=$(echo "$strGlob" | sed 's/\?/\_/g') strGlob=$(echo "$strGlob" | sed 's/\*/\%/g') echo "$strGlob" }
# Append selection criteria and specified parameter to the prepared statement for LIKE operator (case-insensitve) # - Also convert glob metacharacters to SQLite LIKE metacharaters # Note: this has a side-effect of changing global strings $strSelect and $strParams AppendWhereLike() { local columnName=$1 local columnVal=$2 if ! [ "$columnVal" = "*" ]; then strSelect="${strSelect} AND ${columnName} LIKE ?" if ! [ "$strParams" = "" ]; then strParams="${strParams}|" fi local param=`GlobToLike "$columnVal"` strParams="${strParams}${param}" fi }
# Append selection criteria and specified parameter to the prepared statement for GLOB operator (case-sensitve) # Note: this has a side-effect of changing global strings $strSelect and $strParams AppendWhereGlob() { local columnName=$1 local columnVal=$2 if ! [ "$columnVal" = "*" ]; then strSelect="${strSelect} AND ${columnName} GLOB ?" if ! [ "$strParams" = "" ]; then strParams="${strParams}|" fi strParams="${strParams}${columnVal}" fi }
# Used to filter out "match everything" search criteria IsEverythingRegex() { local searchVal="$1" local retVal="False" if [ "$searchVal" = "" ] || [ "$searchVal" = "*" ] || [ "$searchVal" = ".*" ]; then retVal="True" fi echo "$retVal" }
# Append search criteria and specified parameter to the prepared statement using REGEXP operator # Note: This has a side-effect of changing global strings $strSelect and $strParams AppendWhereRegex() { local colName="$1" local colVal="$2" local colDelim="$3" isEverything=$( IsEverythingRegex "$colVal" ) if [ "$isEverything" = "False" ]; then strSelect="${strSelect} AND $colName REGEXP ?" strParams="${strParams}${colDelim}${colVal}" fi }
AppendTimeSlice() { local columnVal=$1 strSelect="${strSelect} AND (Created > ? OR Modified > ?)" if ! [ "$strParams" = "" ]; then strParams="${strParams}|" fi strParams="${strParams}${columnVal}|${columnVal}" }
# Not using regex syntax, but needs to be compatible with # the argument separators AppendTimeSliceRegex() { local colVal=$1 local colDelim="$2" strSelect="${strSelect} AND (Created > ? OR Modified > ?)" strParams="${strParams}${colDelim}${colVal}${colDelim}${colVal}" }
# Instead of "path glob '...'", create a compound WHERE expression with the # first being a simple equality, and the second being a GLOB # Note: This has a side-effect of changing global strings $strSelect and $strParams AppendSpecialSlashStarGlob() { local columnName=$1 local columnVal=$2 strSelect="${strSelect} AND (${columnName} = ? OR ${columnName} GLOB ?)" if ! [ "$strParams" = "" ]; then strParams="${strParams}|" fi strParams="${strParams}${columnVal}|${columnVal}/*" }
# Special case "/usr/include/*" style search IsSpecialSlashStarGlob() { # A rooted path with trailing slash plus a final * wildcard # No other * or ? wildcards present local searchStr='^(/[^\*\?]+)/\*$'
if [[ "$1" =~ $searchStr ]]; then echo "${BASH_REMATCH[1]}" else echo "" fi } #- End file: index/AppendWhereGlob.sh #- Begin file: index/FileQueryViewName.sh SchemaItemExists () { local EPI=$1 local viewName=$2 local viewExists='FALSE' if [ -x "$EPI" ]; then sqlQuery="SELECT CASE WHEN EXISTS (SELECT * FROM sqlite_master WHERE name LIKE ?1) THEN 'TRUE' ELSE 'FALSE' END" viewExists=`$EPI -psprep "$sqlQuery" -psparams "$viewName"` fi echo "$viewExists" }
FileQueryViewName () { local EPI="$1" local hasNewView=`SchemaItemExists "$EPI" "vFilesSimplePOSIX"` if [ "$hasNewView" = "TRUE" ]; then echo "vFilesSimplePOSIX" else echo "vFiles" fi }
FileQueryViewWithPermissionsName () { local EPI="$1" local hasNewView=`SchemaItemExists "$EPI" "vFilesPOSIX"` if [ "$hasNewView" = "TRUE" ]; then echo "vFilesPOSIX" else echo "vFiles" fi } #- End file: index/FileQueryViewName.sh #- Begin file: index/safe_launch.sh # NOTE: This includes code is duplicated from Content-IR # Run TaniumExecWrapper if no arguments passed to script # To include this file, copy/paste: INCLUDE=index/safe_launch.sh # The comment below prevents problems with stripping the $# incorrectly #DONOTCOMMENTPROCESSNEXTLINE if [ $# -eq 0 ]; then if [ "${__max_exec_time_in_sec}" = "" ]; then __max_exec_time_in_sec=55 fi if [ "${__exec_shell}" = "" ]; then __exec_shell=bash fi
kernelName=`uname -s` if [ "${kernelName}" = "Linux" ]; then osName="Linux" elif [ "${kernelName}" = "Darwin" ]; then osName="Mac" else echo "Couldn't determine OS name" exit 0 fi
if ! [ -e Tools/EPI/TaniumExecWrapper ]; then echo "Error: TaniumExecWrapper Not found. Please first run the package:" \ "\"Distribute Tanium Endpoint Index Tools for ${osName}\"" if [ "$TEW_NOT_FOUND_ADDITIONAL_MESSAGE" != "" ]; then echo "$TEW_NOT_FOUND_ADDITIONAL_MESSAGE" fi exit 0 fi # Start real sensor code using TaniumExecWrapper ./Tools/EPI/TaniumExecWrapper --timeout \ ${__max_exec_time_in_sec} -- ${__exec_shell} $0 "ARBITRARY_ARG"
# 3 = exit code if process is killed by TaniumExecWrapper if [ $? -eq 3 ]; then echo "Timeout limit of ${__max_exec_time_in_sec}" \ "second(s) reached and so the process was killed" fi exit 0 fi # The sensor code will go below and be called if any args are # passed to the shell script #- End file: index/safe_launch.sh #------------ INCLUDES END - Do not edit above this line and INCLUDE STARTS -----
# make sure we're operating from the right place # To get to the TC install directory on a sensor go to ".". # To get to the TC install directory in an action, go to "../..".
taniumpath=$(pwd) Toolspath="${taniumpath}/Tools" EPIpath="${Toolspath}/EPI"
EPI="${EPIpath}/TaniumEndpointIndex"
if ! [ -d "$taniumpath" ]; then echo "Error: $taniumpath does not exist on the filesystem" exit fi
if ! [ -x "$EPI" ]; then echo "Error: Could not find Tanium Endpoint Index" exit fi
queryViewName=`FileQueryViewName "$EPI"`
# default limit strLimit=10
bUseRegex="False" bTreatAsRegEx=`percent_decode "0"` strDirectoryPathIn=`percent_decode "%2a"` strFileNameIn=`percent_decode "%2a"` strSizeIn=`percent_decode "%2a"` strHashIn=`percent_decode "%2a"` strHashSHA1In=`percent_decode "%2a"` strHashSHA256In=`percent_decode "%2a"` strMagicNumberIn=`percent_decode "4D5A%2a"` strLimitIn=`percent_decode "300"` strLookBkHrs=`percent_decode "3"` blnExcludeTCEntries=`percent_decode "1"`
if [ "$bTreatAsRegEx" = "1" ]; then bUseRegex=$( CheckEPIRegexSupport "${EPI}" ) fi
strDirectoryPath=`GenerateValidQueryInput "$strDirectoryPathIn" "*"` strFileName=`GenerateValidQueryInput "$strFileNameIn" "*"` strSize=`GenerateValidQueryInput "$strSizeIn" "*"` strHash=`GenerateValidQueryInput "$strHashIn" "*"` strHashSHA1=`GenerateValidQueryInput "$strHashSHA1In" "*"` strHashSHA256=`GenerateValidQueryInput "$strHashSHA256In" "*"` strMagicNumber=`GenerateValidQueryInput "$strMagicNumberIn" "*"` strLimit=`GenerateValidQueryInput "$strLimitIn" $strLimit` intUnixTimeNow=$(date +%s)
# convert input string to integer intLookBkHrs=`expr $strLookBkHrs + 0 2>/dev/null` if [ $? = 2 ]; then intLookBkHrs=-1 fi
if [ $intLookBkHrs -lt 0 ]; then echo "Look back hours value is not valid." exit fi
if [ $intLookBkHrs -gt 168 ]; then echo "Look back hours exceeds maximum allowed." exit else intUnixTimeStart=$(($intUnixTimeNow - $(($intLookBkHrs * 3600)))) fi
strSQLiteOR="||" strSelect="SELECT rtrim(Path, '/') ${strSQLiteOR} '/' ${strSQLiteOR} Name, MD5, SHA1, SHA256 FROM ${queryViewName} WHERE FileId > 0" strParams=""
# remove trailing slash from directory path lastChar=`echo "$strDirectoryPath" | tail -c 2` if [ "$lastChar" = '/' ]; then #DONOTCOMMENTPROCESSNEXTLINE lastCharPos=$((${#strDirectoryPath}-1)) if [ $lastCharPos -gt 0 ]; then strDirectoryPath="`echo "$strDirectoryPath" | head -c $lastCharPos`" fi fi
if [ "$bUseRegex" = "True" ]; then rxDelim='||' strParams='@regex' AppendWhereRegex "Path" "$strDirectoryPath" "$rxDelim" AppendWhereRegex "Name" "$strFileName" "$rxDelim" AppendWhereRegex "Size" "$strSize" "$rxDelim" AppendWhereRegex "MD5" "$strHash" "$rxDelim" AppendWhereRegex "SHA1" "$strHashSHA1" "$rxDelim" AppendWhereRegex "SHA256" "$strHashSHA256" "$rxDelim" AppendWhereRegex "MagicNumber" "$strMagicNumber" "$rxDelim" AppendTimeSliceRegex $intUnixTimeStart "$rxDelim" else specialPathSearch=`IsSpecialSlashStarGlob "${strDirectoryPath}"` if [ -z $specialPathSearch ]; then AppendWhereGlob "Path" "$strDirectoryPath" else AppendSpecialSlashStarGlob "Path" "$specialPathSearch" fi AppendWhereGlob "Name" "$strFileName" AppendWhereLike "Size" "$strSize" AppendWhereLike "MD5" "$strHash" AppendWhereLike "SHA1" "$strHashSHA1" AppendWhereLike "SHA256" "$strHashSHA256" AppendWhereLike "MagicNumber" "$strMagicNumber" AppendTimeSlice $intUnixTimeStart fi
if [ "$blnExcludeTCEntries" = "1" ]; then strSelect="${strSelect} AND Path NOT LIKE '${taniumpath}%'" fi
strSelect="${strSelect} LIMIT ${strLimit}"
strCmd=(${EPI} -psprep "${strSelect}" -psparams "${strParams}")
exec "${strCmd[@]}" | while read line; do echo $line done

