kernelName=`uname -s` if [ "${kernelName}" = "Linux" ]; then osName="Linux" elif [ "${kernelName}" = "Darwin" ]; then osName="Mac" else echo "Couldn't determine OS name" exit 0 fi
if ! [ -e Tools/EPI/TaniumExecWrapper ]; then echo "Error: TaniumExecWrapper Not found. Please first run the package:" \ "\"Distribute Tanium Endpoint Index Tools for ${osName}\"" if [ "$TEW_NOT_FOUND_ADDITIONAL_MESSAGE" != "" ]; then echo "$TEW_NOT_FOUND_ADDITIONAL_MESSAGE" fi exit 0 fi # Start real sensor code using TaniumExecWrapper ./Tools/EPI/TaniumExecWrapper --timeout \ ${__max_exec_time_in_sec} -- ${__exec_shell} $0 "ARBITRARY_ARG"
# 3 = exit code if process is killed by TaniumExecWrapper if [ $? -eq 3 ]; then echo "Timeout limit of ${__max_exec_time_in_sec}" \ "second(s) reached and so the process was killed" fi exit 0 fi # The sensor code will go below and be called if any args are # passed to the shell script #- End file: index/safe_launch.sh #------------ INCLUDES END - Do not edit above this line and INCLUDE STARTS -----
