EPI="${EPIpath}/TaniumEndpointIndex"
if ! [ -d "$taniumpath" ]; then echo "Error: $taniumpath does not exist on the filesystem" exit fi
if ! [ -x "$EPI" ]; then echo "Error: Could not find Tanium Endpoint Index" exit fi
queryViewName=`FileQueryViewName "$EPI"`
# default limit strLimit=10
bUseRegex="False" bTreatAsRegEx=`percent_decode "0"` strDirectoryPathIn=`percent_decode "%2a"` strFileNameIn=`percent_decode "%2a"` strSizeIn=`percent_decode "%2a"` strHashIn=`percent_decode "%2a"` strHashSHA1In=`percent_decode "%2a"` strHashSHA256In=`percent_decode "%2a"` strMagicNumberIn=`percent_decode "FEEDFACE%2a"` strLimitIn=`percent_decode "300"` strLookBkHrs=`percent_decode "3"` blnExcludeTCEntries=`percent_decode "1"`
if [ "$bTreatAsRegEx" = "1" ]; then bUseRegex=$( CheckEPIRegexSupport "${EPI}" ) fi
