if [ $intLookBkHrs -lt 0 ]; then echo "Look back hours value is not valid." exit fi
if [ $intLookBkHrs -gt 168 ]; then echo "Look back hours exceeds maximum allowed." exit else intUnixTimeStart=$(($intUnixTimeNow - $(($intLookBkHrs * 3600)))) fi
