if [ "$bUseRegex" = "True" ]; then rxDelim='||' strParams='@regex' AppendWhereRegex "Path" "$strDirectoryPath" "$rxDelim" AppendWhereRegex "Name" "$strFileName" "$rxDelim" AppendWhereRegex "Size" "$strSize" "$rxDelim" AppendWhereRegex "MD5" "$strHash" "$rxDelim" AppendWhereRegex "SHA1" "$strHashSHA1" "$rxDelim" AppendWhereRegex "SHA256" "$strHashSHA256" "$rxDelim" AppendWhereRegex "MagicNumber" "$strMagicNumber" "$rxDelim" AppendTimeSliceRegex $intUnixTimeStart "$rxDelim" else specialPathSearch=`IsSpecialSlashStarGlob "${strDirectoryPath}"` if [ -z $specialPathSearch ]; then AppendWhereGlob "Path" "$strDirectoryPath" else AppendSpecialSlashStarGlob "Path" "$specialPathSearch" fi AppendWhereGlob "Name" "$strFileName" AppendWhereLike "Size" "$strSize" AppendWhereLike "MD5" "$strHash" AppendWhereLike "SHA1" "$strHashSHA1" AppendWhereLike "SHA256" "$strHashSHA256" AppendWhereLike "MagicNumber" "$strMagicNumber" AppendTimeSlice $intUnixTimeStart fi
if [ "$blnExcludeTCEntries" = "1" ]; then strSelect="${strSelect} AND Path NOT LIKE '${taniumpath}%'" fi
strSelect="${strSelect} LIMIT ${strLimit}"
