#!/bin/sh
# -*- coding: utf-8 -*-
"exec" "env" "TANIUM_SENSOR=1" "`pwd`/python27/python" "$0" "$@"

import hashlib
import traceback
import sys

try:
    import tanium
    from tanium.sensor_io import sensor_input
    try:
        from incident_response import tanium_process
        from incident_response.tanium_process import exceptions as tproc_exceptions
    except ImportError:
        import tanium_process
        from tanium_process import exceptions as tproc_exceptions
    try:
        from incident_response.taniumlib import exceptions as taux_exceptions
        from incident_response.taniumlib import hash
    except ImportError:
        from taniumlib import exceptions as taux_exceptions
        from taniumlib import hash
except (OSError, RuntimeError, ImportError, AttributeError) as e:
    em = 'Error locating necessary files. Ensure Incident Response Tools are deployed. Error was: {}'.format
    sys.exit(em(e))

try:
    from tanium.os_help import win_help
except ImportError:
    pass

MAX_HASH_BYTES = 1024 * 1024 * 1024
PASSABLE_EXCEPTIONS = (tproc_exceptions.ZombieProcess, tproc_exceptions.AccessDenied, tproc_exceptions.NoSuchProcess)


def sensor_main():
    sep = '|#'
    answers = list()
    inputs = sensor_input.SensorInputs()

    inputs.add_param('alg', 'SHA256', 'MD5')
    alg = inputs.get_param('alg') or 'MD5'
    try:
        win_help.disable_file_system_redirection_for_program()
    except (NameError, AttributeError):  # NameError on non-win, Attribute for 32-bit win
        pass
    hasher = getattr(hashlib, alg.lower())
    batch = hash.BatchHash(hasher, max_file_bytes_in_hash_batch=MAX_HASH_BYTES)
    for proc in tanium_process.process_iter():
        try:
            if proc.exe() is not None and len(proc.exe()) > 0:
                batch.add(proc.exe())
        except PASSABLE_EXCEPTIONS:
            pass
    try:
        for r in batch.yield_hash():
            try:
                answers.append('{path}{sep}{hash}'.format(path=r.item, hash=r.hash_digest, sep=sep))
            except AttributeError:
                # r.hash_digest only appears on HashableItem type. Must be UnhashableItem, which has .reason field.
                answers.append('Error hashing {}: {}'.format(r.item, r.reason))

    except taux_exceptions.MaxBytesLimitError as e:
        answers.append('TSE-Error: {}'.format(e))
    # A top level exception caught here and reported as a string is better than having the client catch it, so that
    # answers continue to be generated, and prior answers are seen.
    except Exception as e:
